	private static long uri(long payload) {
		return ValueIds.createId(ValueIds.T_URI, payload);
	}

	private static long inlineInt(long payload) {
		return ValueIds.createId(ValueIds.T_INTEGER, payload);
	}

	private List<String> relativeFileList() throws IOException {
		try (Stream<Path> paths = Files.walk(dataDir.toPath())) {
			return paths.filter(Files::isRegularFile)
					.map(p -> dataDir.toPath().relativize(p).toString())
					.sorted()
					.collect(Collectors.toList());
		}
	}

	@Test
	void scanPredicatesUsesPredicatePrefixRunsWhenAvailable() throws Exception {
		tripleStore.startTransaction();
		for (int i = 0; i < 64; i++) {
			tripleStore.storeTriple(uri(1000 + i), uri(10), uri(2000 + i), 0, true);
			tripleStore.storeTriple(uri(3000 + i), uri(20), uri(4000 + i), 0, true);
		}
		tripleStore.storeTriple(uri(5000), uri(20), uri(6000), 0, false);
		tripleStore.storeTriple(uri(5001), uri(30), uri(6001), 0, false);
		tripleStore.commit();

		LmdbPrefixRunPlan.resetMetrics();
		try (Txn txn = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
			LmdbAdjacencyTripleStoreScanner scanner = new LmdbAdjacencyTripleStoreScanner(tripleStore, txn,
					tripleStore.getDataRevision());
			List<Long> predicates = new ArrayList<>();
			scanner.scanPredicates(predicates::add);

			assertThat(predicates).containsExactly(uri(10), uri(20), uri(30));
		}

		assertThat(LmdbPrefixRunPlan.PLANNED.get()).isEqualTo(2);
		assertThat(LmdbPrefixRunPlan.OPENED.get()).isEqualTo(2);
		assertThat(LmdbPrefixRunPlan.PREFIXES_EMITTED.get()).isEqualTo(4);
	}

	@Test
	void scanPredicatesFallsBackWhenPrefixRunsAreDisabled() throws Exception {
		tripleStore.startTransaction();
		tripleStore.storeTriple(uri(1), uri(10), uri(2), 0, true);
		tripleStore.storeTriple(uri(3), uri(20), uri(4), 0, true);
		tripleStore.commit();

		String previous = System.getProperty(LmdbPrefixRunPlan.ENABLED_PROPERTY);
		try {
			System.setProperty(LmdbPrefixRunPlan.ENABLED_PROPERTY, "false");
			LmdbPrefixRunPlan.resetMetrics();
			try (Txn txn = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
				LmdbAdjacencyTripleStoreScanner scanner = new LmdbAdjacencyTripleStoreScanner(tripleStore, txn,
						tripleStore.getDataRevision());
				List<Long> predicates = new ArrayList<>();
				scanner.scanPredicates(predicates::add);
				assertThat(predicates).containsExactly(uri(10), uri(20));
			}
			assertThat(LmdbPrefixRunPlan.PLANNED.get()).isZero();
			assertThat(LmdbPrefixRunPlan.OPENED.get()).isZero();
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbPrefixRunPlan.ENABLED_PROPERTY);
			} else {
				System.setProperty(LmdbPrefixRunPlan.ENABLED_PROPERTY, previous);
			}
		}
	}

	@Test
	void selectedScansEmitOnlyCoveredPredicateRunsOnDefaultIndexes() throws Exception {
		long selected = uri(20);
		tripleStore.startTransaction();
		for (int subject = 1; subject <= 4; subject++) {
			for (int object = 0; object < 8; object++) {
				tripleStore.storeTriple(uri(subject), uri(10), uri(1_000 + subject * 10 + object), 0, true);
				tripleStore.storeTriple(uri(subject), uri(30), uri(3_000 + subject * 10 + object), 0, true);
			}
			tripleStore.storeTriple(uri(subject), selected, uri(2_000 + subject), 0, true);
		}
		tripleStore.commit();

		LmdbAdjacencyCoverage coverage = LmdbAdjacencyCoverage.selected(new long[] { selected }, Set.of());
		try (Txn txn = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
			LmdbAdjacencyTripleStoreScanner scanner = new LmdbAdjacencyTripleStoreScanner(tripleStore, txn,
					tripleStore.getDataRevision());
			List<Long> outgoingPredicates = new ArrayList<>();
			List<Long> incomingPredicates = new ArrayList<>();
			scanner.scanOutgoing(true, coverage, collectingPredicates(outgoingPredicates));
			scanner.scanIncoming(true, coverage, collectingPredicates(incomingPredicates));

			assertThat(outgoingPredicates).containsExactly(selected, selected, selected, selected);
			assertThat(incomingPredicates).containsExactly(selected, selected, selected, selected);
			Object telemetry = scanner.getClass().getDeclaredMethod("telemetry").invoke(scanner);
			assertThat(invokeLong(telemetry, "cursorRowsScanned")).isLessThanOrEqualTo(16);
			assertThat(invokeLong(telemetry, "cursorRowsMatched")).isEqualTo(8);
			assertThat(invokeLong(telemetry, "cursorRowsSkipped")).isEqualTo(8);
			assertThat(invokeLong(telemetry, "cursorSeeks")).isGreaterThanOrEqualTo(9);
		}
	}

	private static long invokeLong(Object target, String method) throws ReflectiveOperationException {
		return (long) target.getClass().getDeclaredMethod(method).invoke(target);
	}

	@Test
	void buildAndCloseCreatesNoAdjacencyFiles() throws Exception {
		long g1 = uri(9001);
		long[][] quads = {
				{ uri(1), uri(100), uri(2), 0, 1 },
				{ uri(1), uri(100), uri(3), g1, 1 },
				{ uri(2), uri(100), uri(3), 0, 1 },
				{ uri(1), uri(101), inlineInt(42), 0, 1 },
				{ uri(3), uri(101), uri(1), 0, 0 } // inferred
		};
		tripleStore.startTransaction();
		for (long[] quad : quads) {
			tripleStore.storeTriple(quad[0], quad[1], quad[2], quad[3], quad[4] == 1);
		}
		tripleStore.commit();

		List<String> before = relativeFileList();

		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1 << 30);
		try (Txn txn = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
			LmdbAdjacencyTripleStoreScanner scanner = new LmdbAdjacencyTripleStoreScanner(tripleStore, txn,
					tripleStore.getDataRevision());
			assertThat(scanner.supportsOrderedScan(true)).isTrue();
			assertThat(scanner.supportsOrderedScan(false)).isTrue();
			assertThat(scanner.snapshotId()).isEqualTo(mdb_txn_id(txn.get()));

			LmdbInMemoryAdjacencyIndex index = LmdbPagedCsfBaseBuilder.build(scanner, LmdbAdjacencyCoverage.full(),
					account, 1 << 20, 1 << 17);
			try {
				assertThat(index.statementCount()).isEqualTo(quads.length);
				verifyAgainstLmdb(index, txn, quads);
			} finally {
				index.close();
			}
			assertThat(account.totalChargedBytes()).isZero();

			// rebuild from the same snapshot: every restart discards and rebuilds (I1)
			LmdbInMemoryAdjacencyIndex rebuilt = LmdbPagedCsfBaseBuilder.build(scanner,
					LmdbAdjacencyCoverage.full(), account, 1 << 20, 1 << 17);
			try {
				verifyAgainstLmdb(rebuilt, txn, quads);
			} finally {
				rebuilt.close();
			}
		}

		List<String> after = relativeFileList();
		assertThat(after).isEqualTo(before);
		for (String path : after) {
			assertThat(path.toLowerCase())
					.doesNotContain("adjacency")
					.doesNotContain("segment")
					.doesNotContain("manifest")
					.doesNotContain("journal")
					.doesNotContain("checkpoint");
		}
	}

	/**
	 * Differential oracle: every built row decodes to exactly the pinned-transaction LMDB result for the same probe.
	 */
	private void verifyAgainstLmdb(LmdbInMemoryAdjacencyIndex index, Txn txn, long[][] quads) throws IOException {
		TreeSet<String> probed = new TreeSet<>();
		for (long[] quad : quads) {
			boolean explicit = quad[4] == 1;
			int outPlane = explicit ? LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT
					: LmdbAdjacencyPlane.PLANE_OUTGOING_INFERRED;
			int inPlane = explicit ? LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT
					: LmdbAdjacencyPlane.PLANE_INCOMING_INFERRED;
			if (probed.add(quad[0] + "/" + outPlane + "/" + quad[1])) {
				List<long[]> expected = new ArrayList<>();
				try (RecordIterator it = tripleStore.getTriples(txn, quad[0], quad[1], -1, -1, explicit)) {
					long[] row;
					while ((row = it.next()) != null) {
						expected.add(new long[] { row[TripleIndex.OBJ_IDX], row[TripleIndex.CONTEXT_IDX] });
					}
				}
				verifyRow(index, quad[0], outPlane, quad[1], expected);
			}
			if (probed.add(quad[2] + "/" + inPlane + "/" + quad[1])) {
				List<long[]> expected = new ArrayList<>();
				try (RecordIterator it = tripleStore.getTriples(txn, -1, quad[1], quad[2], -1, explicit)) {
					long[] row;
					while ((row = it.next()) != null) {
						expected.add(new long[] { row[TripleIndex.SUBJ_IDX], row[TripleIndex.CONTEXT_IDX] });
					}
				}
				verifyRow(index, quad[2], inPlane, quad[1], expected);
			}
		}
	}

	private void verifyRow(LmdbInMemoryAdjacencyIndex index, long key, int plane, long predicate,
			List<long[]> expected) {
		expected.sort((a, b) -> {
			int cmp = Long.compareUnsigned(a[0], b[0]);
			return cmp != 0 ? cmp : Long.compareUnsigned(a[1], b[1]);
		});
		long handle = index.findRun(key, plane, predicate);
		assertThat(handle).as("row %d/%d/%d", key, plane, predicate).isPositive();
		assertThat(LmdbAdjacencyRunCodec.edgeCount(index.arenaCatalog(), handle)).isEqualTo(expected.size());
		for (int i = 0; i < expected.size(); i++) {
			assertThat(LmdbAdjacencyRunCodec.neighborAt(index.arenaCatalog(), handle, i))
					.isEqualTo(expected.get(i)[0]);
			assertThat(LmdbAdjacencyRunCodec.contextAt(index.arenaCatalog(), index.contextCatalog(), handle, i))
					.isEqualTo(expected.get(i)[1]);
		}
	}

	private static AdjacencySourceScanner.GroupConsumer collectingPredicates(List<Long> predicates) {
		return new AdjacencySourceScanner.GroupConsumer() {
			@Override
			public void begin(long key, long predicate, int plane) {
				predicates.add(predicate);
			}

			@Override
			public void pair(long neighbor, long context) {
			}

			@Override
			public void end() {
			}
		};
	}

